for root, dirs, fs in os.walk(S):
    dirs[:] = [d for d in dirs if d not in (".git",)]
    for fn in fs:
        if fn.endswith(".c"):
            allc.append(os.path.join(root, fn))
print("c files:", len(allc))

def parse_file(abspath):
    try:
        with open(abspath, errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return []
    funcs = []
    i, n = 0, len(lines)
    while i < n:
        m = func_def_re.match(lines[i])
        if m:
            name = m.group(1)
            j = i
            found = None
            while j < n and j < i + 20:
                if lines[j].startswith("{"):
                    found = j; break
                s = lines[j].strip()
                if s == "" or re.match(r'^[A-Za-z_][A-Za-z0-9_ \t\*&,\(\)]*$', s) or s.endswith(")"):
                    j += 1; continue
                break
            if found is not None:
                k = found
                depth = 0; started = False
                while k < n:
                    for ch in lines[k]:
                        if ch == "{": depth += 1; started = True
                        elif ch == "}":
                            depth -= 1
                            if started and depth == 0:
                                funcs.append((name, i+1, k+1))
                                i = k + 1
                                break
                    else:
                        k += 1
                        continue
                    break
                else:
                    pass
                if not (started and depth == 0):
                    i += 1
                    continue
                continue
        i += 1
    return funcs

for p in allc:
    rel = os.path.relpath(p, S)
    fl = parse_file(p)
    if fl:
        file_lists[rel] = fl
        for (name, s, e) in fl:
            defs[name].append((rel, s, e))

json.dump({k: v for k, v in file_lists.items()}, open("all_funcs.json","w"))
print("files with parsed funcs:", len(file_lists), "distinct func names:", len(defs))
